def inserir(no, chave):
    if no is None:
        return {"chave": chave, "esq": None, "dir": None}
    lado = "esq" if chave < no["chave"] else "dir"
    no[lado] = inserir(no[lado], chave)
    return no

def altura(no):
    if no is None:
        return -1
    return 1 + max(altura(no["esq"]), altura(no["dir"]))
raiz = None
for chave in [8, 3, 10, 1, 6, 14, 4, 7, 13, 5]:
    raiz = inserir(raiz, chave)
print(altura(raiz))

